// TypeScript Version: 4.1

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF) for an Erlang distribution.
*
* @param x - input value
* @returns evaluated logCDF
*/
type Unary = ( x: number ) => number;

/**
* Interface for the natural logarithm of the cumulative distribution function (logCDF) of an Erlang distribution.
*/
interface LogCDF {
	/**
	* Evaluates the natural logarithm of the cumulative distribution function (CDF) for an Erlang distribution with shape parameter `k` and rate parameter `lambda` at a value `x`.
	*
	* ## Notes
	*
	* -   If not provided a nonnegative integer for `k`, the function returns `NaN`.
	* -   If provided a non-positive value for `lambda`, the function returns `NaN`.
	*
	* @param x - input value
	* @param k - shape parameter
	* @param lambda - rate parameter
	* @returns evaluated logCDF
	*
	* @example
	* var y = logcdf( 2.0, 1, 1.0 );
	* // returns ~-0.145
	*
	* @example
	* var y = logcdf( 2.0, 3, 1.0 );
	* // returns ~-1.129
	*
	* @example
	* var y = logcdf( 2.0, 2.5, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = logcdf( -1.0, 2, 2.0 );
	* // returns -Infinity
	*
	* @example
	* var y = logcdf( +Infinity, 4, 2.0 );
	* // returns 0.0
	*
	* @example
	* var y = logcdf( -Infinity, 4, 2.0 );
	* // returns -Infinity
	*
	* @example
	* var y = logcdf( NaN, 0, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = logcdf( 0.0, NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = logcdf( 0.0, 0, NaN );
	* // returns NaN
	*
	* @example
	* var y = logcdf( 2.0, -1, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = logcdf( 2.0, 1, -1.0 );
	* // returns NaN
	*/
	( x: number, k: number, lambda: number ): number;

	/**
	* Returns a function for evaluating the natural logarithm of the cumulative distribution function (CDF) for an Erlang distribution with shape parameter `k` and rate parameter `lambda`.
	*
	* @param k - shape parameter
	* @param lambda - rate parameter
	* @returns logCDF
	*
	* @example
	* var myLogCDF = logcdf.factory( 2, 0.1 );
	* var y = myLogCDF( 12.0 );
	* // returns ~-1.087
	*
	* y = myLogCDF( 8.0 );
	* // returns ~-1.654
	*/
	factory( k: number, lambda: number ): Unary;
}

/**
* Erlang distribution natural logarithm of the cumulative distribution function (CDF).
*
* @param x - input value
* @param k - shape parameter
* @param lambda - rate parameter
* @returns evaluated logCDF
*
* @example
* var y = logcdf( 2.0, 8, 3.0 );
* // returns ~-1.36
*
* y = logcdf( 0.0, 1, 1.0 );
* // returns -Infinity
*
* var myLogCDF = logcdf.factory( 2, 0.5 );
* y = myLogCDF( 6.0 );
* // returns ~-0.222
*
* y = myLogCDF( 2.0 );
* // returns ~-1.33
*/
declare var logcdf: LogCDF;


// EXPORTS //

export = logcdf;
